pub struct Client {
    endpoint: String,
    timeout_secs: u64,
}

impl Client {
    pub fn new(endpoint: &str) -> Self {
        Self { endpoint: endpoint.to_string(), timeout_secs: 30 }
    }
    pub fn with_timeout(mut self, secs: u64) -> Self {
        self.timeout_secs = secs;
        self
    }
}
